# frozen_string_literal: true

require "yaml"

module Crops
  # The month farmers in a region really plant a crop, from
  # config/crops/planting_calendars.yml (USDA NASS weekly crop progress: the
  # month of the median date the state reaches 50 % planted, last ten years;
  # generated by docs/proposal/validation/calendars.rb). Used before the FAO-56
  # table's row, which plants Iowa corn on 1 April when half of it is in the
  # ground only by about 6 May (the hindcast, studies V7 and V8).
  #
  # A crop or a place without a calendar answers nil, and the caller falls back
  # to the FAO-56 row for its hemisphere (Crops::WaterNeed.default_month).
  module PlantingCalendar
    PATH = Rails.root.join("config/crops/planting_calendars.yml")

    module_function

    def data = (@data ||= PATH.exist? ? YAML.safe_load_file(PATH).to_h.freeze : {}.freeze)

    # Planting month (1-12) for a crop (a FieldCrop, key or name) in a country
    # (ISO code) and region (Farm#admin_area, any case), or nil.
    def month(crop, country_code: nil, admin_area: nil) = entry(crop, country_code: country_code, admin_area: admin_area)&.dig("planting_month")

    # The whole calendar row ({ "planting_month", "planted_10", "planted_50", "planted_90", "years" }) or nil.
    def entry(crop, country_code: nil, admin_area: nil)
      return nil if country_code.blank? || admin_area.blank?

      key = Agronomy.find(crop)&.key or return nil
      regions = data[country_code.to_s.upcase].to_h
      region = regions.keys.find { |name| name.casecmp?(admin_area.to_s.strip) }
      region && regions[region][key]
    end

    # The place a field belongs to, as #month expects it.
    def place_of(record)
      farm = record.respond_to?(:farm) ? record.farm : nil
      { country_code: farm&.country_code, admin_area: farm&.admin_area }
    end

    def reset! = (@data = nil)
  end
end
